#!/usr/bin/env node
// Freshness gate for the committed napi artifacts (index.d.ts, index.js).
//
// WHY THIS EXISTS
// ---------------
// `index.d.ts` and `index.js` are generated by `napi build` but COMMITTED, so a
// fresh clone and every registry consumer can `require()` the package before any
// local build. `.gitignore` says in as many words that they must be kept in sync
// with `src/lib.rs` BY HAND, and nothing enforced it. PR #160 added
// `#[napi] pub async fn query_sql` and very nearly shipped without `querySql` in
// the declarations, which would have left a TypeScript consumer of the published
// package unable to see that the method exists at all.
//
// WHY IT IS NOT A PLAIN `git diff` AFTER THE BUILD
// ------------------------------------------------
// That is the obvious shape, and it is what the C header gate (cbindgen) does.
// Here it would be WRONG, and this was measured rather than assumed: running
// `napi build` on a clean tree today deletes 8 declarations -
//
//   QueryIrCapabilities, QueryIrDirection, QueryIrIndexConsistency,
//   QueryIrRequest, QueryIrResponse, QueryIrSearchMode,
//   QueryIrSearchOperation, QueryIrTraverseOperation
//
// - and downgrades two method signatures to `any`. napi cannot generate any of
// it: the Rust types are plain serde structs (`QueryIrOperation` is an enum with
// struct variants, which `#[napi(object)]` cannot express) and the methods take
// and return `serde_json::Value`, which napi renders as `any`. So a
// regenerate-and-diff gate would be RED ON A CLEAN TREE, and the only way to
// make it green would be to commit a regeneration that deletes those
// declarations - turning a freshness gate into the cause of the drift it exists
// to catch.
//
// WHAT THIS DOES INSTEAD
// ----------------------
// It reconstructs "what napi would generate" from the committed file by undoing
// exactly the hand-maintained parts, then requires an EXACT, ORDERED match with
// what napi actually generated. Every other line - every signature, parameter,
// type and doc comment, in order - is held to a byte-for-byte contract.
//
// The exemptions are self-validating: if a declaration this script expects to
// remove is not there, or a signature it expects to restore is not found, it
// fails rather than quietly exempting nothing. An exemption that stops matching
// is itself a defect.
//
// Usage: node scripts/check-dts-freshness.mjs <committed-dir> [generated-dir]

import { readFileSync, existsSync } from 'node:fs'
import { join } from 'node:path'

// Top-level declarations written by hand because napi cannot express them.
// Matched by name prefix so a new QueryIr* type does not need to be listed.
const HAND_WRITTEN_PREFIX = 'QueryIr'
const HAND_WRITTEN_EXPECTED = 8

// Method signatures deliberately narrowed by hand from what napi emits.
// generated line -> the committed line that replaces it.
const HAND_REFINED = new Map([
  [
    '  executeQueryIr(request: any): Promise<any>',
    '  executeQueryIr(request: QueryIrRequest): Promise<QueryIrResponse>',
  ],
  ['  queryIrCapabilities(): any', '  queryIrCapabilities(): QueryIrCapabilities'],
])

function fail(message) {
  console.error(`::error::${message}`)
  process.exitCode = 1
}

/**
 * Line endings are NOT part of the contract and must be normalised before any
 * comparison. The committed files carry CRLF (napi wrote them on a Windows dev
 * host); the same `napi build` on the Linux CI runner emits LF. A byte-exact
 * compare would therefore fail on every platform, every time, for a difference
 * that says nothing about whether a declaration is missing.
 */
function normalise(text) {
  return text.replace(/\r\n/g, '\n')
}

/**
 * Drop every top-level `export interface|type|const enum <PREFIX>...` block.
 * Interface and enum blocks run to a column-0 `}`; `type` aliases are one line.
 * Returns the surviving lines and how many declarations were removed.
 */
function stripHandWritten(lines, prefix) {
  const kept = []
  let removed = 0
  let i = 0
  while (i < lines.length) {
    const line = lines[i]
    const decl = /^export (?:interface|type|const enum|declare class) ([A-Za-z0-9_]+)/.exec(line)
    if (decl && decl[1].startsWith(prefix)) {
      removed += 1
      if (line.includes('{')) {
        // Block form: skip to the closing brace in column 0.
        i += 1
        while (i < lines.length && lines[i] !== '}') i += 1
        i += 1 // step past the `}`
      } else {
        i += 1 // one-line `type X = ...`
      }
      continue
    }
    kept.push(line)
    i += 1
  }
  return { kept, removed }
}

function reconstructGenerated(committedText) {
  const { kept, removed } = stripHandWritten(normalise(committedText).split('\n'), HAND_WRITTEN_PREFIX)

  if (removed !== HAND_WRITTEN_EXPECTED) {
    fail(
      `expected to strip ${HAND_WRITTEN_EXPECTED} hand-written ${HAND_WRITTEN_PREFIX}* ` +
        `declarations from index.d.ts, stripped ${removed}. The exemption list in ` +
        `scripts/check-dts-freshness.mjs no longer matches the file - update HAND_WRITTEN_EXPECTED ` +
        `deliberately rather than letting the gate exempt the wrong thing.`,
    )
    return null
  }

  // Put napi's own (wider) signatures back, so the comparison sees them.
  const restored = new Set()
  const out = kept.map((line) => {
    for (const [generated, committed] of HAND_REFINED) {
      if (line === committed) {
        restored.add(generated)
        return generated
      }
    }
    return line
  })

  if (restored.size !== HAND_REFINED.size) {
    const missing = [...HAND_REFINED]
      .filter(([generated]) => !restored.has(generated))
      .map(([, committed]) => committed.trim())
    fail(
      `expected ${HAND_REFINED.size} hand-refined signature(s) in index.d.ts, found ` +
        `${restored.size}. Not found: ${missing.join(' | ')}. An exemption that no longer ` +
        `matches is a stale exemption - fix the list, do not ignore it.`,
    )
    return null
  }

  return out.join('\n')
}

function reportDiff(label, expected, actual) {
  const e = expected.split('\n')
  const a = actual.split('\n')
  const shown = []
  for (let i = 0; i < Math.max(e.length, a.length) && shown.length < 20; i += 1) {
    if (e[i] !== a[i]) {
      shown.push(`  line ${i + 1}:`)
      shown.push(`    committed (after undoing hand edits): ${e[i] ?? '<end of file>'}`)
      shown.push(`    napi generated:                       ${a[i] ?? '<end of file>'}`)
    }
  }
  fail(
    `${label} is out of date with src/lib.rs.\n${shown.join('\n')}\n` +
      `Add or update the declaration BY HAND. Do NOT commit the output of ` +
      `\`napi build\` wholesale: it deletes the hand-written ${HAND_WRITTEN_PREFIX}* ` +
      `declarations. See the note at the top of scripts/check-dts-freshness.mjs.`,
  )
}

function main() {
  const [committedDir, generatedDir = '.'] = process.argv.slice(2)
  if (!committedDir) {
    fail('usage: node scripts/check-dts-freshness.mjs <committed-dir> [generated-dir]')
    return
  }

  for (const dir of [committedDir, generatedDir]) {
    for (const name of ['index.d.ts', 'index.js']) {
      if (!existsSync(join(dir, name))) {
        fail(`missing ${join(dir, name)} - nothing to compare, so this gate would pass vacuously`)
        return
      }
    }
  }

  const committedDts = readFileSync(join(committedDir, 'index.d.ts'), 'utf8')
  const generatedDts = normalise(readFileSync(join(generatedDir, 'index.d.ts'), 'utf8'))
  const reconstructed = reconstructGenerated(committedDts)
  if (reconstructed === null) return

  if (reconstructed !== generatedDts) {
    reportDiff('index.d.ts', reconstructed, generatedDts)
  }

  // index.js carries no per-method content (it exports the class, whose methods
  // ride along), so it is compared as-is - no exemptions needed.
  const committedJs = normalise(readFileSync(join(committedDir, 'index.js'), 'utf8'))
  const generatedJs = normalise(readFileSync(join(generatedDir, 'index.js'), 'utf8'))
  if (committedJs !== generatedJs) {
    fail('index.js differs from what `napi build` generated. Commit the regenerated file.')
  }

  if (!process.exitCode) {
    console.log(
      `index.d.ts and index.js are in sync with src/lib.rs ` +
        `(${HAND_WRITTEN_EXPECTED} hand-written ${HAND_WRITTEN_PREFIX}* declarations and ` +
        `${HAND_REFINED.size} hand-refined signatures accounted for).`,
    )
  }
}

main()
